<script setup lang="ts">
import {computed,nextTick,onMounted,ref} from 'vue'
import {workspaceService,type AreaEntity} from '../services/workspace'
import {areaChanges} from '../services/areaManagement'
const props=defineProps<{initialAreaUid?:string;startCreate?:boolean}>()
const palette=['#246b55','#328b82','#5784b5','#8372b0','#af7893','#bc8a54','#84915a','#697a8c']
const emit=defineEmits<{close:[];changed:[]}>()
const dialog=ref<HTMLDialogElement>(),nameInput=ref<HTMLInputElement>()
const areas=ref<AreaEntity[]>([]),selected=ref<AreaEntity>(),name=ref(''),color=ref('#557a68'),query=ref(''),showArchived=ref(false),busy=ref(false),error=ref(''),confirmDelete=ref(false),confirmation=ref('')
const activeCount=computed(()=>areas.value.filter(a=>!a.archived).length)
const hasChanges=computed(()=>!!selected.value&&(name.value!==selected.value.name||color.value!==(selected.value.color||'#557a68')))
const visible=computed(()=>areas.value.filter(a=>(showArchived.value||!a.archived)&&a.name.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())).sort((a,b)=>Number(a.archived)-Number(b.archived)||a.sortOrder-b.sortOrder))
function edit(area?:AreaEntity){selected.value=area;name.value=area?.name||'';color.value=area?.color||'#557a68';confirmDelete.value=false;confirmation.value='';error.value='';void nextTick(()=>nameInput.value?.focus())}
async function load(){areas.value=await workspaceService.areas()}
async function run(action:()=>Promise<unknown>,afterSuccess?:()=>void){if(busy.value)return;busy.value=true;error.value='';try{await action();if(afterSuccess)afterSuccess();else{await load();edit()}emit('changed')}catch(e){error.value=e instanceof Error?e.message:'领域操作失败，请重试'}finally{busy.value=false}}
function save(){void run(()=>{const changes=areaChanges(name.value,color.value);return selected.value?workspaceService.updateArea(selected.value,changes):workspaceService.createArea({...changes,kind:'custom',sortOrder:Math.max(-1,...areas.value.map(a=>a.sortOrder))+1,archived:false})})}
function archive(){const area=selected.value;if(area)void run(()=>workspaceService.updateArea(area,{archived:!area.archived}))}
function remove(){const area=selected.value;if(area&&confirmation.value===area.name)void run(()=>workspaceService.removeArea(area),()=>{areas.value=areas.value.filter(item=>item.uid!==area.uid);edit()})}
function close(){if(busy.value)return;if(confirmDelete.value){confirmDelete.value=false;error.value='';return}emit('close')}
onMounted(async()=>{dialog.value?.showModal();busy.value=true;try{await load();edit(props.startCreate?undefined:areas.value.find(a=>a.uid===props.initialAreaUid)||areas.value.find(a=>!a.archived))}catch(e){error.value=e instanceof Error?e.message:'无法加载领域'}finally{busy.value=false}})
</script>
<template>
 <Teleport to="body"><dialog ref="dialog" class="area-manager" aria-labelledby="area-manager-title" @cancel.prevent="close">
  <header class="manager-heading"><div class="manager-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/></svg></div><div><small>工作空间</small><h2 id="area-manager-title">领域管理</h2><p>让每件事，都有自己的位置。</p></div><button type="button" class="manager-close" aria-label="关闭领域管理" :disabled="busy" @click="close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg></button></header>
  <div class="area-manager-body"><aside><label class="manager-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg><input v-model="query" aria-label="搜索领域" placeholder="搜索领域…"/></label><div class="manager-list-heading"><span>我的领域</span><small>{{activeCount}} 个使用中</small></div><div class="area-manager-list"><button v-for="area in visible" :key="area.uid" type="button" :aria-label="area.name+(area.archived?' 已归档':'')" :disabled="busy" :class="{selected:selected?.uid===area.uid}" @click="edit(area)"><i :style="{color:area.color||'#557a68',background:(area.color||'#557a68')+'18'}">{{area.name.slice(0,1)}}</i><span><b>{{area.name}}</b><small>{{area.archived?'已归档':'使用中'}}</small></span><em v-if="selected?.uid===area.uid">›</em></button><div v-if="!visible.length" class="area-empty"><span>没有匹配的领域</span><small>换个关键词，或创建新领域</small></div></div><label class="area-archived"><input v-model="showArchived" type="checkbox"/>显示已归档</label><button type="button" class="manager-new" :disabled="busy" @click="edit()"><span>＋</span>新建领域</button></aside>
  <section class="manager-detail" :aria-busy="busy"><div :style="{visibility:confirmDelete?'hidden':undefined}" :inert="confirmDelete"><div class="detail-heading"><i :style="{color,background:color+'16'}">{{name.trim().slice(0,1)||'＋'}}</i><div><small>{{selected?(selected.archived?'已归档领域':'使用中的领域'):'新的开始'}}</small><h3>{{selected?.name||'创建一个领域'}}</h3><p>{{selected?'管理名称、标识与使用状态':'例如工作、生活、学习，让关注点更清晰。'}}</p></div></div>
   <form @submit.prevent="save"><div class="manager-field-heading"><label for="area-name">领域名称</label><small>{{name.length}} / 80</small></div><input id="area-name" ref="nameInput" v-model="name" aria-label="领域名称" maxlength="80" required :disabled="busy||confirmDelete" placeholder="给这个领域起一个名字"/><small class="field-help">简短、明确的名称，更容易在切换时找到。</small>
    <div class="manager-field-heading color-heading"><label for="area-color">标识颜色</label><small>{{color.toUpperCase()}}</small></div><div class="manager-palette"><button v-for="tone in palette" :key="tone" type="button" class="color-swatch" :style="{background:tone}" :aria-label="'使用颜色 '+tone" :aria-pressed="color===tone" :disabled="busy||confirmDelete" @click="color=tone"><span v-if="color===tone">✓</span></button><label class="custom-color" for="area-color"><input id="area-color" v-model="color" type="color" aria-label="标识颜色" :disabled="busy||confirmDelete"/><span>自定义</span></label></div>
    <footer class="manager-save"><span>{{hasChanges?'有未保存的修改':selected?'名称和颜色可随时调整':'创建后可用于组织项目、笔记和任务'}}</span><button class="area-primary" :disabled="busy||confirmDelete||!name.trim()||!!selected&&!hasChanges">{{busy?'处理中…':selected?'保存修改':'保存'}}</button></footer></form>
   <div v-if="selected" class="manager-lifecycle"><div><span class="lifecycle-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h16v12H4zM3 4h18v4H3zM9 12h6"/></svg></span><div><h4>{{selected.archived?'重新使用这个领域':'暂时不再关注？'}}</h4><p>{{selected.archived?'恢复后重新出现在领域切换中。':'归档后收起入口，所有内容和归属仍保留。'}}</p></div></div><button type="button" :disabled="busy||confirmDelete||hasChanges" @click="archive">{{selected.archived?'恢复领域':'归档领域'}}</button></div>
   <div v-if="selected" class="area-danger-zone"><div class="delete-summary"><span>只想移除空领域？</span><button type="button" class="area-danger-link" :disabled="busy" @click="confirmDelete=!confirmDelete;confirmation='';error=''">删除领域…</button></div></div></div>
   <div v-if="confirmDelete&&selected" class="delete-confirm" role="alertdialog" aria-labelledby="area-delete-title" aria-describedby="area-delete-message"><span class="delete-mark" aria-hidden="true">×</span><small>删除领域</small><h3 id="area-delete-title">删除「{{selected.name}}」？</h3><p id="area-delete-message" class="delete-message" :class="{failed:error}" :role="error?'alert':undefined">{{error||'只能删除没有关联内容的领域，回收站内容也会保留归属。删除后无法恢复；如果只是暂时不用，可以选择归档。'}}</p><label>输入领域名称确认<input v-model="confirmation" aria-label="确认删除领域名称" :disabled="busy" :placeholder="selected.name" autofocus/></label><footer><button type="button" :disabled="busy" @click="confirmDelete=false;error=''">返回</button><button type="button" class="area-danger" :disabled="busy||confirmation!==selected.name" @click="remove"><span v-if="busy" class="delete-spinner" aria-hidden="true"/>{{busy?'正在核对并删除…':'确认删除'}}</button></footer></div>
  </section></div><footer class="area-manager-bottom"><span v-if="error&&!confirmDelete" role="alert" class="manager-feedback">{{error}}</span><span v-else><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 4 6v6c0 4 8 9 8 9s8-5 8-9V6l-8-3Zm-4 9 3 3 5-6"/></svg>归档与恢复不会删除内容</span><button type="button" :disabled="busy" @click="close">完成</button></footer>
 </dialog></Teleport>
</template>
